def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    components = []

    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            comp = []
            while stack:
                x, y = stack.pop()
                comp.append((x, y))
                for nx, ny in ((x - 1, y), (x + 1, y), (x, y - 1), (x, y + 1)):
                    if 0 <= nx < h and 0 <= ny < w and grid[nx][ny] == 0 and (nx, ny) not in seen:
                        seen.add((nx, ny))
                        stack.append((nx, ny))
            components.append(comp)

    background = max(range(len(components)), key=lambda i: len(components[i]))
    out = [row[:] for row in grid]
    for i, comp in enumerate(components):
        if i == background:
            continue
        color = 7 if len(comp) <= 4 else 8
        for r, c in comp:
            out[r][c] = color
    return out
